pub(crate) fn admit(&mut self, now: Instant) -> Result<SlotIndex, AdmissionError> {
    if self.occupied_count >= MAX_TUNNELS {
        return Err(AdmissionError::SlotCapacity);
    }
    if self.pending_count >= MAX_PENDING_SETUPS {
        return Err(AdmissionError::PendingCapacity);
    }
    let index = self.take_min_free();
    self.slots[index as usize] = SlotState::InSetup {
        setup_deadline: Deadline::setup(now),
        attempts: AttemptLedger::new(),
    };
    self.occupied_count += 1;
    self.pending_count += 1;

if let Some(delim) = self.find_delimiter() {
    let head_len = delim + END_OF_HEAD.len();
    let head = &self.head[..delim];
    self.result = Some(parse_request(head));
    self.head_len = head_len;
    return Ok(Feed::Complete { head_len });
}
if take < data.len() {
    return Err(ConnectError::TooLong);
}
Ok(Feed::Incomplete)

fn admit(&mut self, stream: TcpStream) {
    let now = Instant::now();
    match self.storage.accept(now) {
        Err(_) => {
            let client = stream.peer_addr().ok();
            let secs = self.storage.cache_secs(now);
            let mut s = stream;
            write_all_bounded(&mut s, BODY_503);
            self.storage
                .logs_mut()
                .reject(secs, RejectReason::Capacity, client, None);
            self.note_occupancy(now);

