fn project_tripwire(&mut self, index: usize, violation: Violation) -> Effect {
    let secs = self.storage.cache_secs(Instant::now());
    let effect = {
        let slot = &mut self.slots[index];
        let en = self.storage.enforcement_mut();
        en.decide(&mut slot.first_slot, violation, secs)
    };
    if let Some(fact) = captured_fact(violation) {
        self.stamp_capture(index, fact, effect);
    }
    match effect {
        Effect::Block { scope: Scope::All } => self.stop_block_all(),
        Effect::Block {
            scope: Scope::Domain,
        } => {
            if let Violation::EarlyUpstreamData { ordinal } | Violation::Ja4Change { ordinal } =
                violation
            {
                self.stop_domain_block(ordinal, index);
            }
        }
        _ => {}
    }
    effect
}

